#!/usr/bin/env python3
"""回查道具的异称与指代上下文；仅输出候选，不自动认定同一实物。"""
import argparse
import json
from asset_validation import input_errors
from prop_identity import prop_candidates, related_props


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('scenes_file')
    parser.add_argument('assets_file')
    parser.add_argument('prop_id', nargs='?')
    parser.add_argument('--terms', nargs='*', default=[], help='补充疑似异称/简称，仅供本次回查')
    parser.add_argument('--related', action='store_true', help='列出可能重复的道具对，不直接合并')
    parser.add_argument('--json', action='store_true', help='以 JSON 输出原文候选位置')
    args = parser.parse_args()
    try:
        with open(args.scenes_file, encoding='utf-8') as stream:
            data = json.load(stream)
        with open(args.assets_file, encoding='utf-8') as stream:
            assets = json.load(stream)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        parser.exit(1, f'错误: 无法读取 JSON：{error}\n')
    errors = input_errors(data, assets)
    if errors:
        parser.exit(1, '\n'.join(errors) + '\n')
    if args.related:
        print(json.dumps(list(related_props(assets)), ensure_ascii=False, indent=2))
        return
    prop = next((item for item in assets['props'] if item['id'] == args.prop_id), None)
    if prop is None:
        parser.error('指定有效的道具 ID，或使用 --related')
    matches = list(prop_candidates(data, prop, args.terms))
    if args.json:
        print(json.dumps(matches, ensure_ascii=False, indent=2))
        return
    by_scene = {}
    for item in matches:
        by_scene.setdefault(item['source']['scene_id'], []).append(item)
    for ep in data['episodes']:
        for scene in ep['scenes']:
            if scene['scene_id'] not in by_scene:
                continue
            print(f'\n# {scene["scene_id"]} {scene["location"]} {scene["int_ext"]} {scene["time"]}')
            print('候选称呼：' + '、'.join(dict.fromkeys(item['raw_name'] for item in by_scene[scene['scene_id']])))
            print('人物：' + '、'.join(scene['characters']))
            for line_no, line in enumerate(scene['lines'], 1):
                prefix = '▲ ' if line['type'] == 'action' else (line.get('speaker', '') + '：' if line['type'] == 'dialog' else '')
                print(f'L{line_no} {prefix}{line["text"]}')


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""输出人物全剧候选场次及带行号原文。命中不代表出镜，须人工判读。

用法: python3 show_character.py <scenes.json> <人物名> [别名 ...]
"""
import json
import sys
import argparse
from character_changes import change_candidates


def candidates(data, names):
    for ep in data['episodes']:
        for scene in ep['scenes']:
            reasons = []
            if set(names) & set(scene.get('characters', [])):
                reasons.append('人物行')
            if any(line.get('speaker') in names for line in scene.get('lines', [])):
                reasons.append('对白/画外音（须判读）')
            if any(any(name in line.get('text', '') for name in names)
                   for line in scene.get('lines', [])):
                reasons.append('正文提及（须判读）')
            if reasons:
                yield ep, scene, reasons


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('scenes_file')
    parser.add_argument('names', nargs='+')
    parser.add_argument('--changes', action='store_true', help='输出独立外观候选 JSON，供填写 change_reviews')
    args = parser.parse_args()
    with open(args.scenes_file, encoding='utf-8') as stream:
        data = json.load(stream)
    names = args.names
    if args.changes:
        char = {'name': names[0], 'aliases': names[1:]}
        print(json.dumps(list(change_candidates(data, char)), ensure_ascii=False, indent=2))
        return
    for ep, scene, reasons in candidates(data, names):
        print(f'\n# 第{ep["episode"]}集 {scene["scene_id"]} {scene["location"]} {scene["int_ext"]} {scene["time"]}')
        print('命中：' + '、'.join(reasons))
        print('人物：' + '、'.join(scene.get('characters', [])))
        for i, line in enumerate(scene.get('lines', []), 1):
            if line['type'] == 'dialog':
                voice = f'[{line.get("voice")}]' if line.get('voice') else ''
                print(f'L{i} {line["speaker"]}{voice}：{line["text"]}')
            else:
                prefix = '▲ ' if line['type'] == 'action' else ''
                print(f'L{i} {prefix}{line["text"]}')


if __name__ == '__main__':
    main()

